    pub contact_raw: Option<String>,
    pub contact_params: Option<HashMap<String, String>>,
    pub path: Option<Vec<rsip::Uri>>,
    pub service_route: Option<Vec<rsip::Uri>>,
    pub instance_id: Option<String>,
