        let token = token.clone();
        router = router.route(
            ws_handler,
            axum::routing::get(
                async move |client_ip: ClientAddr, ws: WebSocketUpgrade| -> Response {
                    let token = token.clone();
                    ws.protocols(["sip"]).on_upgrade(async move |socket| {
                        sip_ws_handler(token, client_ip, socket, endpoint_ref.clone()).await
                    })
                },
            ),
        );
    }

