impl CallController {
    /// Create a controller and its paired timer-fire channel.
    ///
    /// The returned `UnboundedReceiver<String>` **must** be passed to
    /// [`AppEventLoop::new`] so fired timer IDs reach `on_timeout`.
    pub fn new(
        session: SipSessionHandle,
        event_rx: mpsc::UnboundedReceiver<ControllerEvent>,
    ) -> (Self, mpsc::UnboundedReceiver<String>) {
        let (fired_timer_tx, fired_timer_rx) = mpsc::unbounded_channel();
        let ctrl = Self {
            session,
            event_rx,
            fired_timer_tx,
            cancelled_timers: Arc::new(Mutex::new(HashSet::new())),
        };
        (ctrl, fired_timer_rx)
    }

    /// Answer the call (send 200 OK).
    pub async fn answer(&self) -> anyhow::Result<()> {
        self.session.send_command(SessionAction::AcceptCall {
            callee: None,
            sdp: None,
            dialog_id: None,
        })?;
        Ok(())
    }

    pub async fn hangup(
        &self,
        reason: Option<CallRecordHangupReason>,
        code: Option<u16>,
    ) -> anyhow::Result<()> {
        self.session.send_command(SessionAction::Hangup {
            reason,
            code,
            initiator: Some("app".to_string()),
        })?;
        Ok(())
    }

    pub async fn transfer(&self, target: impl Into<String>) -> anyhow::Result<()> {
        let target = target.into();
        self.session
            .send_command(SessionAction::from_transfer_target(&target))?;
        Ok(())
    }

    /// Play an audio file.
    ///
    /// The `interruptible` flag determines if DTMF input should stop playback.
    /// Returns a handle to the playback session.
    pub async fn play_audio(
        &self,
        file: impl Into<String>,
        _interruptible: bool,
    ) -> anyhow::Result<PlaybackHandle> {
        self.play_audio_with_options(file, None, false, _interruptible)
            .await
    }

    /// Play an audio file with full control over track ID, looping, and
    /// DTMF interruptibility.
    ///
    /// - `track_id` – caller-assigned unique ID; a UUID is generated when `None`.
    /// - `loop_playback` – when `true`, the file loops until explicitly stopped.
    /// - `interruptible` – whether DTMF should stop playback (handled by the app).
    pub async fn play_audio_with_options(
        &self,
        file: impl Into<String>,
        track_id: Option<String>,
        loop_playback: bool,
        interruptible: bool,
    ) -> anyhow::Result<PlaybackHandle> {
        let path = file.into();
        let track_id = track_id.unwrap_or_else(|| uuid::Uuid::new_v4().to_string());
        self.session.send_command(SessionAction::PlayPrompt {
            audio_file: path.clone(),
            send_progress: false,
            await_completion: true,
            track_id: Some(track_id.clone()),
            loop_playback,
            interrupt_on_dtmf: interruptible,
        })?;

        Ok(PlaybackHandle {
            track_id,
            file_path: path,
        })
    }

    /// Stop current audio playback.
    pub async fn stop_audio(&self) -> anyhow::Result<()> {
        self.session.send_command(SessionAction::StopPlayback)?;
        Ok(())
    }

    /// Register a named one-shot timer.
    ///
    /// After `delay`, [`CallApp::on_timeout`] will be invoked with `id`.
    ///
    /// Calling `set_timeout` with the same `id` before it fires **re-registers**
    /// the timer (the previous one is cancelled). Use [`cancel_timeout`](Self::cancel_timeout)
    /// to suppress a pending fire without re-registering.
    ///
    /// # Panics
    /// Will not panic; timer tasks are fire-and-forget on a Tokio runtime.
    pub fn set_timeout(&self, id: impl Into<String>, delay: Duration) {
        let id = id.into();
        // If re-registering, un-cancel any previous suppression.
        self.cancelled_timers.lock().unwrap().remove(&id);
        let tx = self.fired_timer_tx.clone();
        let cancelled = self.cancelled_timers.clone();
        let id_task = id.clone();
        tokio::spawn(async move {
            tokio::time::sleep(delay).await;
            // Only fire if not cancelled in the meantime.
            let was_cancelled = cancelled.lock().unwrap().remove(&id_task);
            if !was_cancelled {
                let _ = tx.send(id_task);
            }
        });
    }

    /// Cancel a pending timer previously registered with [`set_timeout`](Self::set_timeout).
    ///
    /// If the timer has already fired, this is a no-op.
    pub fn cancel_timeout(&self, id: &str) {
        self.cancelled_timers.lock().unwrap().insert(id.to_string());
    }

    /// Start recording the call audio.
    pub async fn start_recording(
        &self,
        path: impl Into<String>,
        max_duration: Option<Duration>,
        beep: bool,
    ) -> anyhow::Result<RecordingHandle> {
        let p = path.into();
        self.session.send_command(SessionAction::StartRecording {
            path: p.clone(),
            max_duration,
            beep,
        })?;
        Ok(RecordingHandle { path: p })
    }

    /// Stop the active recording and wait for completion.
    ///
    /// Sends a stop command and waits for the `RecordingComplete` event.
    /// Returns the recording info including path, duration, and file size.
    ///
    /// # Errors

                        }
                    }
                }
            }
        }
    }

    let https_config = if let Some((cert, key)) = ssl_config {
        match RustlsConfig::from_pem_file(&cert, &key).await {
            Ok(c) => Some(c),
            Err(e) => {
                tracing::error!("Failed to load SSL certs: {}", e);
                None
            }
        }
    } else {
        None
    };

    // Register HTTPS reloader for ACME auto-renew hot-reload
    if let Some(ref config) = https_config {
        let reloader = Arc::new(crate::tls_reloader::AxumRustlsReloader::new(Arc::new(
            config.clone(),
        )));
        if let Some(registry_guard) = state.tls_reloader.read().await.as_ref() {
            registry_guard.register_https(reloader).await;
        }
    }

    let https_addr = if https_config.is_some() {
        let addr_str = state
            .config()
            .https_addr
            .as_deref()
            .unwrap_or("0.0.0.0:8443");
        match addr_str.parse::<SocketAddr>() {
            Ok(a) => Some(a),
            Err(e) => {
                tracing::error!("Invalid HTTPS address {}: {}", addr_str, e);
                None
            }
        }
    } else {
        None
    };

    if let Some(addr) = https_addr {
        info!("HTTPS enabled on {}", addr);
    }

    let http_task = axum::serve(
        listener,
        router
            .clone()
            .into_make_service_with_connect_info::<SocketAddr>(),
    );

    let https_router = if https_addr.is_some() {
        router.layer(middleware::from_fn(
            |mut req: axum::extract::Request, next: axum::middleware::Next| async move {
                req.headers_mut()
                    .insert("x-forwarded-proto", "https".parse().unwrap());
                next.run(req).await
            },
        ))
    } else {
        router
    };

    select! {
        http_result = http_task => {
            match http_result {
                Ok(_) => info!("Server shut down gracefully"),
                Err(e) => {
                    tracing::error!("Server error: {}", e);
                    return Err(anyhow::anyhow!("Server error: {}", e));
                }
            }
        }
        https_result = async {
            if let (Some(config), Some(addr)) = (https_config, https_addr) {
                 axum_server::bind_rustls(addr, config)
                    .serve(https_router.into_make_service_with_connect_info::<SocketAddr>())
                    .await
            } else {
                std::future::pending().await
            }
        } => {
             match https_result {
                Ok(_) => info!("HTTPS Server shut down gracefully"),
                Err(e) => {
                    tracing::error!("HTTPS Server error: {}", e);
                    return Err(anyhow::anyhow!("HTTPS Server error: {}", e));
                }
            }
        }
        prx_result = state.sip_server().serve()  => {
            if let Err(e) = prx_result {
                tracing::error!("Sip server error: {}", e);
            }
        }
        _ = token.cancelled() => {
            info!("Application shutting down due to cancellation");
        }
    }
    Ok(())
}

// ICE servers handler
async fn iceservers_handler(State(state): State<AppState>) -> impl IntoResponse {
    let ice_servers = state.config().ice_servers.clone().unwrap_or_default();
    Json(ice_servers).into_response()
}

pub fn create_router(state: AppState) -> Router {
    let mut router = Router::new();

    // Serve static files
    let static_files_service = ServeDir::new("static");

    // If static/index.html exists, serve it at the root
    if std::path::Path::new("static/index.html").exists() {
        router = router.route(
            "/",
            get(|| async {
                match tokio::fs::read_to_string("static/index.html").await {
                    Ok(content) => Html(content).into_response(),
                    Err(_) => StatusCode::NOT_FOUND.into_response(),
                }
            }),
        );
    }

    // CORS configuration to allow cross-origin requests
    let cors = CorsLayer::new()
        .allow_origin(AllowOrigin::any())
        .allow_methods([
            axum::http::Method::GET,
            axum::http::Method::POST,
            axum::http::Method::PUT,
            axum::http::Method::DELETE,
            axum::http::Method::OPTIONS,
        ])
        .allow_headers([
            axum::http::header::CONTENT_TYPE,
            axum::http::header::AUTHORIZATION,
            axum::http::header::ACCEPT,
            axum::http::header::ORIGIN,
        ]);

    // Merge call and WebSocket handlers with static file serving
    let call_routes = crate::handler::ami_router(state.clone()).with_state(state.clone());
    #[allow(unused_mut)]
    let mut router = router
        .route(
            "/iceservers",
            get(iceservers_handler).with_state(state.clone()),
        )
        .merge(state.addon_registry.get_routers(state.clone()))
        .nest_service("/static", static_files_service)
        .merge(call_routes)
        .layer(cors);

    // Add RWI WebSocket endpoint if configured
    if let (Some(auth), Some(gateway), Some(call_registry)) = (
        state.core.rwi_auth.clone(),
        state.core.rwi_gateway.clone(),
        state.core.rwi_call_registry.clone(),
    ) {
        let rwi_auth = auth;
        let rwi_gateway = gateway;
        let rwi_call_registry = call_registry;
        let rwi_sip_server: Option<crate::proxy::server::SipServerRef> =
            Some(state.sip_server().get_inner());
        router = router.route(
            "/rwi/v1",
            axum::routing::get(
                async move |client_addr: crate::handler::middleware::clientaddr::ClientAddr,
                            ws: axum::extract::ws::WebSocketUpgrade,
                            axum::extract::Query(params): axum::extract::Query<
                    std::collections::HashMap<String, String>,
                >,
                            headers: axum::http::HeaderMap| {
                    use axum::Extension;
                    use axum::extract::Query;

                    crate::rwi::handler::rwi_ws_handler(
                        client_addr,
                        ws,
                        Query(params),
                        Extension(rwi_auth),
                        Extension(rwi_gateway),
                        Extension(rwi_call_registry),
                        Extension(rwi_sip_server),
                        headers,
                    )
                    .await
                },
            ),
        );
    }

    #[cfg(feature = "console")]
    if let Some(console_state) = state.console.clone() {
        router = router.merge(crate::console::router(console_state));
    }

    let access_log_skip_paths = Arc::new(state.config().http_access_skip_paths.clone());

    router = router.layer(middleware::from_fn_with_state(
        access_log_skip_paths,
        crate::handler::middleware::request_log::log_requests,
    ));

    if state.config().http_gzip {
        router = router.layer(CompressionLayer::new().gzip(true));
    }

    router
}

use crate::proxy::proxy_call::sip_session::SipSessionHandle;
use chrono::{DateTime, Utc};
use serde::Serialize;
use std::collections::HashMap;
use std::sync::Mutex;

#[derive(Copy, Clone, Debug, Eq, PartialEq, Serialize)]
pub enum ActiveProxyCallStatus {
    Ringing,
    Talking,
}

impl ToString for ActiveProxyCallStatus {
    fn to_string(&self) -> String {
        match self {
            ActiveProxyCallStatus::Ringing => "ringing".to_string(),
            ActiveProxyCallStatus::Talking => "talking".to_string(),
        }
    }
}

#[derive(Clone, Debug, Serialize)]
pub struct ActiveProxyCallEntry {
    pub session_id: String,
    pub caller: Option<String>,
    pub callee: Option<String>,
    pub direction: String,
    pub started_at: DateTime<Utc>,
    pub answered_at: Option<DateTime<Utc>>,
    pub status: ActiveProxyCallStatus,
}

#[derive(Default)]
struct RegistryState {
    entries: HashMap<String, ActiveProxyCallEntry>,
    handles: HashMap<String, SipSessionHandle>,
    handles_by_dialog: HashMap<String, SipSessionHandle>,
    // session_id -> all registered dialog_ids (multiple dialogs per session during failover)
    dialog_by_session: HashMap<String, Vec<String>>,
}

pub struct ActiveProxyCallRegistry {
    inner: Mutex<RegistryState>,
}

impl ActiveProxyCallRegistry {
    pub fn new() -> Self {
        Self {
            inner: Mutex::new(RegistryState::default()),
        }
    }

    pub fn upsert(&self, entry: ActiveProxyCallEntry, handle: SipSessionHandle) {
        let mut guard = self.inner.lock().unwrap();
        guard.entries.insert(entry.session_id.clone(), entry);
        guard
            .handles
            .insert(handle.session_id().to_string(), handle);
    }

    pub fn register_dialog(&self, dialog_id: String, handle: SipSessionHandle) {
        let mut guard = self.inner.lock().unwrap();
        guard
            .dialog_by_session
            .entry(handle.session_id().to_string())
            .or_default()
            .push(dialog_id.clone());
        guard.handles_by_dialog.insert(dialog_id, handle);
    }

    pub fn unregister_dialog(&self, dialog_id: &str) {
        let mut guard = self.inner.lock().unwrap();
        if let Some(handle) = guard.handles_by_dialog.remove(dialog_id) {
            if let Some(dialogs) = guard.dialog_by_session.get_mut(handle.session_id()) {
                dialogs.retain(|d| d != dialog_id);
                if dialogs.is_empty() {
                    guard.dialog_by_session.remove(handle.session_id());
                }
            }
        }
    }

    pub fn get_handle_by_dialog(&self, dialog_id: &str) -> Option<SipSessionHandle> {
        let guard = self.inner.lock().unwrap();
        guard.handles_by_dialog.get(dialog_id).cloned()
    }

    pub fn update<F>(&self, session_id: &str, updater: F)
    where
        F: FnOnce(&mut ActiveProxyCallEntry),
    {
        if let Some(entry) = self.inner.lock().unwrap().entries.get_mut(session_id) {
            updater(entry);
        }
    }

    pub fn remove(&self, session_id: &str) {
        let mut guard = self.inner.lock().unwrap();
        guard.entries.remove(session_id);
        guard.handles.remove(session_id);
        // Remove all dialog handles registered for this session
        if let Some(dialog_ids) = guard.dialog_by_session.remove(session_id) {
            for dialog_id in dialog_ids {
                guard.handles_by_dialog.remove(&dialog_id);
            }
        }
    }

    pub fn count(&self) -> usize {
        self.inner.lock().unwrap().entries.len()
    }

    pub fn list_recent(&self, limit: usize) -> Vec<ActiveProxyCallEntry> {
        let mut entries: Vec<_> = self
            .inner
            .lock()
            .unwrap()
            .entries
            .values()
            .cloned()
            .collect();
        entries.sort_by(|a, b| b.started_at.cmp(&a.started_at));
        if entries.len() > limit {
            entries.truncate(limit);
        }
        entries
    }

    pub fn get(&self, session_id: &str) -> Option<ActiveProxyCallEntry> {
        self.inner.lock().unwrap().entries.get(session_id).cloned()
    }

    pub fn get_handle(&self, session_id: &str) -> Option<SipSessionHandle> {
        self.inner.lock().unwrap().handles.get(session_id).cloned()
    }

    /// Get all active session IDs
    pub fn session_ids(&self) -> Vec<String> {
        self.inner.lock().unwrap().entries.keys().cloned().collect()
    }

    /// Alias for count() for SessionRegistry compatibility
    pub fn len(&self) -> usize {
        self.count()
    }

    /// Register a unified session handle
    /// This is used by SipSession to register itself
    pub fn register_handle(&self, session_id: String, handle: SipSessionHandle) {
        let entry = ActiveProxyCallEntry {
            session_id: session_id.clone(),
            caller: None,
            callee: None,
            direction: "inbound".to_string(),
            started_at: Utc::now(),
            answered_at: None,
            status: ActiveProxyCallStatus::Ringing,
        };
        self.upsert(entry, handle);
    }

    #[cfg(test)]
    pub fn handles_by_dialog_count(&self) -> usize {
        self.inner.lock().unwrap().handles_by_dialog.len()
    }

    #[cfg(test)]
    pub fn dialog_by_session_count(&self) -> usize {
        self.inner.lock().unwrap().dialog_by_session.len()
    }

    /// Cleanup stale entries that have been inactive for longer than max_age
    /// Returns the number of entries removed
    pub fn cleanup_stale(&self, max_age: std::time::Duration) -> usize {
        let cutoff = Utc::now() - chrono::Duration::from_std(max_age).unwrap_or_else(|_| chrono::Duration::hours(1));
        let mut guard = self.inner.lock().unwrap();

        let stale_ids: Vec<String> = guard
            .entries
            .iter()
            .filter(|(_, entry)| {
                let last_activity = entry.answered_at.unwrap_or(entry.started_at);
                last_activity < cutoff
            })
            .map(|(id, _)| id.clone())
            .collect();

        let count = stale_ids.len();
        for id in stale_ids {
            guard.entries.remove(&id);
            guard.handles.remove(&id);
            if let Some(dialog_ids) = guard.dialog_by_session.remove(&id) {
                for dialog_id in dialog_ids {
                    guard.handles_by_dialog.remove(&dialog_id);
                }
            }
        }

        count
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::proxy::proxy_call::sip_session::SipSession;

    fn make_handle(session_id: &str) -> SipSessionHandle {
        use crate::call::runtime::SessionId;

        let id = SessionId::from(session_id);
        let (handle, _cmd_rx) = SipSession::with_handle(id);
        handle
    }

    fn make_entry(session_id: &str) -> ActiveProxyCallEntry {
        ActiveProxyCallEntry {
            session_id: session_id.to_string(),
            caller: None,
            callee: None,
            direction: "outbound".to_string(),
            started_at: chrono::Utc::now(),
            answered_at: None,
            status: ActiveProxyCallStatus::Ringing,
        }
    }

    /// Before fix: dialog_by_session stored only the LAST dialog, so remove() only
    /// cleaned the last entry — all previous handles_by_dialog entries leaked.
    /// After fix: all dialog ids are tracked and fully cleaned on remove().
    #[test]
    fn test_remove_cleans_all_dialog_handles() {
        let registry = ActiveProxyCallRegistry::new();
        let session = "session-1";
        let handle = make_handle(session);
        let entry = make_entry(session);

        // Simulate the sequence that happens during a real call:
        // 1. register_active_call  → registers server dialog
        registry.upsert(entry, handle.clone());
        registry.register_dialog("server-dialog".to_string(), handle.clone());
        assert_eq!(registry.handles_by_dialog_count(), 1);

        // 2. add_callee_dialog (trunk 1 attempt)
        registry.register_dialog("callee-dialog-1".to_string(), handle.clone());
        assert_eq!(registry.handles_by_dialog_count(), 2);

        // 3. add_callee_dialog (failover trunk 2)
        registry.register_dialog("callee-dialog-2".to_string(), handle.clone());
        assert_eq!(registry.handles_by_dialog_count(), 3);

        // All 3 dialogs should be tracked under this session
        assert_eq!(
            registry.inner.lock().unwrap().dialog_by_session[session].len(),
            3
        );

        // 4. Session ends → remove() must clean ALL three handles_by_dialog entries
        registry.remove(session);

//! Queue Manager for RWI CallCommand
//!
//! Manages call queue operations including enqueue, dequeue, priority management,
//! and position tracking for queued legs.

use crate::call::domain::LegId;
use crate::call::runtime::SessionId;
use anyhow::{Result, anyhow};
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use tokio::sync::RwLock;
use tracing::info;

/// Unique identifier for a queue
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct QueueId(pub String);

impl From<String> for QueueId {
    fn from(s: String) -> Self {
        Self(s)
    }
}

impl From<&str> for QueueId {
    fn from(s: &str) -> Self {
        Self(s.to_string())
    }
}

/// Entry in the queue for a specific leg
#[derive(Debug, Clone)]
pub struct QueueEntry {
    pub leg_id: LegId,
    pub session_id: SessionId,
    pub priority: u32,
    pub enqueued_at: std::time::Instant,
    pub position_announcements_enabled: bool,
}

impl QueueEntry {
    pub fn new(leg_id: LegId, session_id: SessionId, priority: Option<u32>) -> Self {
        Self {
            leg_id,
            session_id,
            priority: priority.unwrap_or(5), // Default priority (1-10, lower is higher priority)
            enqueued_at: std::time::Instant::now(),
            position_announcements_enabled: true,
        }
    }
}

/// Queue state and configuration
#[derive(Debug, Clone)]
pub struct CallQueue {
    pub id: QueueId,
    pub entries: VecDeque<QueueEntry>,
    pub max_wait_time: Option<std::time::Duration>,
    pub announcement_interval: Option<std::time::Duration>,
}

impl CallQueue {
    pub fn new(id: QueueId) -> Self {
        Self {
            id,
            entries: VecDeque::new(),
            max_wait_time: None,
            announcement_interval: Some(std::time::Duration::from_secs(30)),
        }
    }

    /// Add entry to queue with priority ordering
    pub fn enqueue(&mut self, entry: QueueEntry) -> usize {
        let position = self
            .entries
            .iter()
            .position(|e| e.priority > entry.priority)
            .unwrap_or(self.entries.len());
        self.entries.insert(position, entry);
        position + 1 // Return 1-based position
    }

    /// Remove entry from queue by leg_id
    pub fn dequeue(&mut self, leg_id: &LegId) -> Option<QueueEntry> {
        if let Some(pos) = self.entries.iter().position(|e| e.leg_id == *leg_id) {
            self.entries.remove(pos)
        } else {
            None
        }
    }

    /// Get position of a leg in the queue (1-based)
    pub fn get_position(&self, leg_id: &LegId) -> Option<usize> {
        self.entries.iter().position(|e| e.leg_id == *leg_id).map(|p| p + 1)
    }

    /// Get queue length
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

/// Global queue manager
#[derive(Debug)]
pub struct QueueManager {
    queues: Arc<RwLock<HashMap<QueueId, CallQueue>>>,
}

impl QueueManager {
    pub fn new() -> Self {
        Self {
            queues: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    /// Create or get a queue
    pub async fn get_or_create_queue(&self, queue_id: QueueId) -> CallQueue {
        let mut queues = self.queues.write().await;
        queues
            .entry(queue_id.clone())
            .or_insert_with(|| CallQueue::new(queue_id))
            .clone()
    }

    /// Get a queue if it exists
    pub async fn get_queue(&self, queue_id: &QueueId) -> Option<CallQueue> {
        let queues = self.queues.read().await;
        queues.get(queue_id).cloned()
    }

    /// Enqueue a leg to a queue
    pub async fn enqueue(
        &self,
        queue_id: QueueId,
        leg_id: LegId,
        session_id: SessionId,
        priority: Option<u32>,
    ) -> Result<usize> {
        let mut queues = self.queues.write().await;
        let queue = queues
            .entry(queue_id.clone())
            .or_insert_with(|| CallQueue::new(queue_id));

        let entry = QueueEntry::new(leg_id.clone(), session_id, priority);
        let position = queue.enqueue(entry);

        info!(
            queue_id = %queue.id.0,
            leg_id = %leg_id,
            position = position,
            "Leg enqueued successfully"
        );

        Ok(position)
    }

    /// Dequeue a leg from a queue
    pub async fn dequeue(&self, queue_id: &QueueId, leg_id: &LegId) -> Result<QueueEntry> {
        let mut queues = self.queues.write().await;
        let queue = queues
            .get_mut(queue_id)
            .ok_or_else(|| anyhow!("Queue not found: {}", queue_id.0))?;

        let entry = queue
            .dequeue(leg_id)
            .ok_or_else(|| anyhow!("Leg {} not found in queue {}", leg_id, queue_id.0))?;

        info!(
            queue_id = %queue.id.0,
            leg_id = %leg_id,
            "Leg dequeued successfully"
        );

        Ok(entry)
    }

    /// Get position of a leg in a queue
    pub async fn get_position(&self, queue_id: &QueueId, leg_id: &LegId) -> Result<usize> {
        let queues = self.queues.read().await;
        let queue = queues
            .get(queue_id)
            .ok_or_else(|| anyhow!("Queue not found: {}", queue_id.0))?;

        queue
            .get_position(leg_id)
            .ok_or_else(|| anyhow!("Leg {} not found in queue {}", leg_id, queue_id.0))
    }

    /// Get queue statistics
    pub async fn get_queue_stats(&self, queue_id: &QueueId) -> Result<QueueStats> {
        let queues = self.queues.read().await;
        let queue = queues
            .get(queue_id)
            .ok_or_else(|| anyhow!("Queue not found: {}", queue_id.0))?;

        Ok(QueueStats {
            queue_id: queue_id.0.clone(),
            length: queue.len(),
            wait_times: queue
                .entries
                .iter()
                .map(|e| e.enqueued_at.elapsed())
                .collect(),
        })
    }

    /// List all queues
    pub async fn list_queues(&self) -> Vec<QueueId> {
        let queues = self.queues.read().await;
        queues.keys().cloned().collect()
    }

    /// Remove a queue if empty
    pub async fn remove_queue_if_empty(&self, queue_id: &QueueId) -> Result<bool> {
        let mut queues = self.queues.write().await;
        if let Some(queue) = queues.get(queue_id) {
            if queue.is_empty() {
                queues.remove(queue_id);
                info!(queue_id = %queue_id.0, "Empty queue removed");
                return Ok(true);
            }
        }
        Ok(false)
    }

    /// Get all entries in a queue
    pub async fn get_queue_entries(&self, queue_id: &QueueId) -> Result<Vec<QueueEntry>> {
        let queues = self.queues.read().await;
        let queue = queues
            .get(queue_id)
            .ok_or_else(|| anyhow!("Queue not found: {}", queue_id.0))?;

        Ok(queue.entries.iter().cloned().collect())
    }
}

impl Default for QueueManager {
    fn default() -> Self {
        Self::new()
    }
}

/// Queue statistics
#[derive(Debug, Clone)]
pub struct QueueStats {
    pub queue_id: String,
    pub length: usize,
    pub wait_times: Vec<std::time::Duration>,
}

#[cfg(test)]
mod tests {
