429	                let license_cfg = app_state.config().licenses.clone();
430	                let results =
431	                    crate::license::check_all_addon_licenses(&commercial_ids, &license_cfg).await;
432	                if !results.is_empty() {
433	                    tracing::info!(
434	                        "License check at startup: {} addon(s) verified",
435	                        results.len()
436	                    );
437	                    crate::license::record_startup_results(results);
438	                }
439	            }
440	        }
441	
442	        #[cfg(feature = "console")]
443	        {
444	            if let Some(ref console_state) = app_state.console {
445	                // Spawn background update checker only when the console is enabled
446	                // (checks miuda.ai/api/check_update at startup, then every 24 hours).
447	                crate::version::spawn_update_checker(db_conn.clone(), token.clone());
448	                console_state.set_sip_server(Some(app_state.sip_server().get_inner()));
449	                // Register addon locale directories into the i18n manager before
450	                // binding the app_state so that all subsequent renders pick up the
451	                // merged translations immediately.
452	                for (addon_id, locale_dir) in
453	                    app_state.addon_registry.get_locale_dirs(app_state.clone())
454	                {
455	                    console_state
456	                        .i18n()
457	                        .register_addon_locales(&addon_id, locale_dir);
458	                }
459	                console_state.set_app_state(Some(Arc::downgrade(&app_state)));
460	            }
461	        }
462	
463	        Ok(app_state)
464	    }
465	}
