467	pub async fn run(state: AppState, mut router: Router) -> Result<()> {
468	    let token = state.token().clone();
469	    let addr: SocketAddr = state.config().http_addr.parse()?;
470	    let listener = match TcpListener::bind(addr).await {
471	        Ok(l) => l,
472	        Err(e) => {
473	            tracing::error!("Failed to bind to {}: {}", addr, e);
474	            return Err(anyhow::anyhow!("Failed to bind to {}: {}", addr, e));
475	        }
476	    };
477	
478	    if let Some(ref ws_handler) = state.sip_server().inner.proxy_config.ws_handler {
479	        info!(
480	            "Registering WebSocket handler to sip server: {}",
481	            ws_handler
482	        );
483	        let endpoint_ref = state.sip_server().inner.endpoint.inner.clone();
484	        let token = token.clone();
485	        router = router.route(
486	            ws_handler,
487	            axum::routing::get(
488	                async move |client_ip: ClientAddr, ws: WebSocketUpgrade| -> Response {
489	                    let token = token.clone();
490	                    ws.protocols(["sip"]).on_upgrade(async move |socket| {
491	                        sip_ws_handler(token, client_ip, socket, endpoint_ref.clone()).await
492	                    })
493	                },
494	            ),
495	        );
496	    }
497	
498	    // Check for HTTPS config
499	    let mut ssl_config = None;
500	    if let (Some(cert), Some(key)) = (
501	        &state.config().ssl_certificate,
502	        &state.config().ssl_private_key,
503	    ) {
504	        ssl_config = Some((cert.clone(), key.clone()));
505	    } else {
506	        // Auto-detect from config/certs
507	        let cert_dir = std::path::Path::new("config/certs");
508	        if cert_dir.exists() {
509	            if let Ok(entries) = std::fs::read_dir(cert_dir) {
510	                for entry in entries.flatten() {
511	                    let path = entry.path();
512	                    if path.extension().and_then(|s| s.to_str()) == Some("crt") {
513	                        let key_path = path.with_extension("key");
514	                        if key_path.exists() {
515	                            ssl_config = Some((
516	                                path.to_string_lossy().to_string(),
517	                                key_path.to_string_lossy().to_string(),
518	                            ));
519	                            break;
520	                        }
521	                    }
522	                }
523	            }
524	        }
525	    }
526	
527	    let https_config = if let Some((cert, key)) = ssl_config {
528	        match RustlsConfig::from_pem_file(&cert, &key).await {
529	            Ok(c) => Some(c),
530	            Err(e) => {
531	                tracing::error!("Failed to load SSL certs: {}", e);
532	                None
533	            }
534	        }
535	    } else {
536	        None
537	    };
538	
539	    // Register HTTPS reloader for ACME auto-renew hot-reload
540	    if let Some(ref config) = https_config {
541	        let reloader = Arc::new(crate::tls_reloader::AxumRustlsReloader::new(Arc::new(
542	            config.clone(),
543	        )));
544	        if let Some(registry_guard) = state.tls_reloader.read().await.as_ref() {
545	            registry_guard.register_https(reloader).await;
546	        }
547	    }
548	
549	    let https_addr = if https_config.is_some() {
550	        let addr_str = state
551	            .config()
552	            .https_addr
553	            .as_deref()
554	            .unwrap_or("0.0.0.0:8443");
555	        match addr_str.parse::<SocketAddr>() {
556	            Ok(a) => Some(a),
557	            Err(e) => {
558	                tracing::error!("Invalid HTTPS address {}: {}", addr_str, e);
559	                None
560	            }
561	        }
562	    } else {
563	        None
564	    };
565	
566	    if let Some(addr) = https_addr {
567	        info!("HTTPS enabled on {}", addr);
568	    }
569	
570	    let http_task = axum::serve(
571	        listener,
572	        router
573	            .clone()
574	            .into_make_service_with_connect_info::<SocketAddr>(),
575	    );
576	
577	    let https_router = if https_addr.is_some() {
578	        router.layer(middleware::from_fn(
579	            |mut req: axum::extract::Request, next: axum::middleware::Next| async move {
580	                req.headers_mut()
581	                    .insert("x-forwarded-proto", "https".parse().unwrap());
582	                next.run(req).await
583	            },
584	        ))
585	    } else {
586	        router
587	    };
588	
589	    select! {
590	        http_result = http_task => {
591	            match http_result {
592	                Ok(_) => info!("Server shut down gracefully"),
593	                Err(e) => {
594	                    tracing::error!("Server error: {}", e);
595	                    return Err(anyhow::anyhow!("Server error: {}", e));
596	                }
597	            }
598	        }
599	        https_result = async {
600	            if let (Some(config), Some(addr)) = (https_config, https_addr) {
601	                 axum_server::bind_rustls(addr, config)
602	                    .serve(https_router.into_make_service_with_connect_info::<SocketAddr>())
603	                    .await
604	            } else {
605	                std::future::pending().await
606	            }
607	        } => {
608	             match https_result {
609	                Ok(_) => info!("HTTPS Server shut down gracefully"),
610	                Err(e) => {
611	                    tracing::error!("HTTPS Server error: {}", e);
612	                    return Err(anyhow::anyhow!("HTTPS Server error: {}", e));
613	                }
614	            }
615	        }
616	        prx_result = state.sip_server().serve()  => {
617	            if let Err(e) = prx_result {
618	                tracing::error!("Sip server error: {}", e);
619	            }
620	        }
621	        _ = token.cancelled() => {
622	            info!("Application shutting down due to cancellation");
623	        }
624	    }
625	    Ok(())
626	}
