284	    pub async fn build(mut self) -> Result<SipServer> {
285	        let user_backend = if let Some(backend) = self.user_backend {
286	            backend
287	        } else {
288	            match build_user_backend(self.config.as_ref()).await {
289	                Ok(backend) => backend,
290	                Err(e) => {
291	                    warn!(
292	                        "failed to create user backend: {} {:?}",
293	                        e, &self.config.user_backends
294	                    );
295	                    return Err(e);
296	                }
297	            }
298	        };
299	        let auth_backend = self.auth_backend;
300	        let locator = if let Some(locator) = self.locator {
301	            locator
302	        } else {
303	            match create_locator(&self.config.locator).await {
304	                Ok(locator) => locator,
305	                Err(e) => {
306	                    warn!("failed to create locator: {} {:?}", e, self.config.locator);
307	                    return Err(e);
