 42	impl RwiGateway {
 43	    pub fn new() -> Self {
 44	        Self {
 45	            sessions: HashMap::new(),
 46	            session_event_senders: HashMap::new(),
 47	            context_subscriptions: HashMap::new(),
 48	            call_ownership: HashMap::new(),
 49	            supervisor_calls: HashMap::new(),
 50	        }
 51	    }
