 73	        let position = self
 74	            .entries
 75	            .iter()
 76	            .position(|e| e.priority > entry.priority)
 77	            .unwrap_or(self.entries.len());
 78	        self.entries.insert(position, entry);
 79	        position + 1 // Return 1-based position
 80	    }
 81	
 82	    /// Remove entry from queue by leg_id
 83	    pub fn dequeue(&mut self, leg_id: &LegId) -> Option<QueueEntry> {
 84	        if let Some(pos) = self.entries.iter().position(|e| e.leg_id == *leg_id) {
 85	            self.entries.remove(pos)
 86	        } else {
 87	            None
 88	        }
 89	    }
 90	
 91	    /// Get position of a leg in the queue (1-based)
 92	    pub fn get_position(&self, leg_id: &LegId) -> Option<usize> {
 93	        self.entries.iter().position(|e| e.leg_id == *leg_id).map(|p| p + 1)
 94	    }
 95	
 96	    /// Get queue length
 97	    pub fn len(&self) -> usize {
 98	        self.entries.len()
 99	    }
100	
101	    pub fn is_empty(&self) -> bool {
102	        self.entries.is_empty()
103	    }
104	}
