119	    /// Create or get a queue
120	    pub async fn get_or_create_queue(&self, queue_id: QueueId) -> CallQueue {
121	        let mut queues = self.queues.write().await;
122	        queues
123	            .entry(queue_id.clone())
124	            .or_insert_with(|| CallQueue::new(queue_id))
125	            .clone()
126	    }
