128	    /// Get a queue if it exists
129	    pub async fn get_queue(&self, queue_id: &QueueId) -> Option<CallQueue> {
130	        let queues = self.queues.read().await;
131	        queues.get(queue_id).cloned()
132	    }
133	
134	    /// Enqueue a leg to a queue
135	    pub async fn enqueue(
136	        &self,
137	        queue_id: QueueId,
138	        leg_id: LegId,
139	        session_id: SessionId,
140	        priority: Option<u32>,
141	    ) -> Result<usize> {
142	        let mut queues = self.queues.write().await;
143	        let queue = queues
144	            .entry(queue_id.clone())
145	            .or_insert_with(|| CallQueue::new(queue_id));
146	
147	        let entry = QueueEntry::new(leg_id.clone(), session_id, priority);
148	        let position = queue.enqueue(entry);
149	
150	        info!(
151	            queue_id = %queue.id.0,
152	            leg_id = %leg_id,
153	            position = position,
154	            "Leg enqueued successfully"
155	        );
156	
157	        Ok(position)
158	    }
159	
160	    /// Dequeue a leg from a queue
161	    pub async fn dequeue(&self, queue_id: &QueueId, leg_id: &LegId) -> Result<QueueEntry> {
162	        let mut queues = self.queues.write().await;
163	        let queue = queues
164	            .get_mut(queue_id)
165	            .ok_or_else(|| anyhow!("Queue not found: {}", queue_id.0))?;
166	
167	        let entry = queue
168	            .dequeue(leg_id)
169	            .ok_or_else(|| anyhow!("Leg {} not found in queue {}", leg_id, queue_id.0))?;
170	
171	        info!(
172	            queue_id = %queue.id.0,
173	            leg_id = %leg_id,
174	            "Leg dequeued successfully"
175	        );
176	
177	        Ok(entry)
178	    }
179	
180	    /// Get position of a leg in a queue
181	    pub async fn get_position(&self, queue_id: &QueueId, leg_id: &LegId) -> Result<usize> {
182	        let queues = self.queues.read().await;
183	        let queue = queues
184	            .get(queue_id)
185	            .ok_or_else(|| anyhow!("Queue not found: {}", queue_id.0))?;
186	
187	        queue
188	            .get_position(leg_id)
189	            .ok_or_else(|| anyhow!("Leg {} not found in queue {}", leg_id, queue_id.0))
190	    }
