192	    /// Get queue statistics
193	    pub async fn get_queue_stats(&self, queue_id: &QueueId) -> Result<QueueStats> {
194	        let queues = self.queues.read().await;
195	        let queue = queues
196	            .get(queue_id)
197	            .ok_or_else(|| anyhow!("Queue not found: {}", queue_id.0))?;
198	
199	        Ok(QueueStats {
200	            queue_id: queue_id.0.clone(),
201	            length: queue.len(),
202	            wait_times: queue
203	                .entries
204	                .iter()
205	                .map(|e| e.enqueued_at.elapsed())
206	                .collect(),
207	        })
208	    }
