216	    /// Remove a queue if empty
217	    pub async fn remove_queue_if_empty(&self, queue_id: &QueueId) -> Result<bool> {
218	        let mut queues = self.queues.write().await;
219	        if let Some(queue) = queues.get(queue_id) {
220	            if queue.is_empty() {
221	                queues.remove(queue_id);
222	                info!(queue_id = %queue_id.0, "Empty queue removed");
223	                return Ok(true);
224	            }
225	        }
226	        Ok(false)
227	    }
