229	    /// Get all entries in a queue
230	    pub async fn get_queue_entries(&self, queue_id: &QueueId) -> Result<Vec<QueueEntry>> {
231	        let queues = self.queues.read().await;
232	        let queue = queues
233	            .get(queue_id)
234	            .ok_or_else(|| anyhow!("Queue not found: {}", queue_id.0))?;
235	
236	        Ok(queue.entries.iter().cloned().collect())
