 63	    pub fn new(config: &StorageConfig) -> Result<Self> {
 64	        match config {
 65	            StorageConfig::Local { path } => {
 66	                let root = PathBuf::from(path);
 67	                std::fs::create_dir_all(&root)
 68	                    .with_context(|| format!("create storage directory {}", path))?;
 69	                let store = LocalFileSystem::new_with_prefix(&root)?;
 70	                Ok(Self {
 71	                    inner: Arc::new(store),
 72	                    prefix: "".to_string(),
 73	                    is_local: true,
 74	                    local_root: Some(root),
 75	                })
 76	            }
 77	            StorageConfig::S3 {
 78	                vendor,
 79	                bucket,
 80	                region,
 81	                access_key,
 82	                secret_key,
 83	                endpoint,
 84	                prefix,
 85	            } => {
 86	                let store: Arc<dyn ObjectStore> = match vendor {
 87	                    S3Vendor::AWS
 88	                    | S3Vendor::Aliyun
 89	                    | S3Vendor::Tencent
 90	                    | S3Vendor::Minio
 91	                    | S3Vendor::DigitalOcean => {
 92	                        let mut builder = AmazonS3Builder::new()
 93	                            .with_bucket_name(bucket)
 94	                            .with_region(region)
 95	                            .with_access_key_id(access_key)
 96	                            .with_secret_access_key(secret_key);
 97	
 98	                        if let Some(ep) = endpoint {
 99	                            if !ep.is_empty() {
100	                                builder = builder.with_endpoint(ep);
101	                            }
102	                        }
103	                        Arc::new(builder.build()?)
104	                    }
105	                    S3Vendor::GCP => {
106	                        let instance = GoogleCloudStorageBuilder::new()
107	                            .with_bucket_name(bucket)
108	                            .with_service_account_key(secret_key)
109	                            .build()?;
110	                        Arc::new(instance)
111	                    }
112	                    S3Vendor::Azure => {
113	                        let instance = MicrosoftAzureBuilder::new()
114	                            .with_container_name(bucket)
115	                            .with_account(access_key)
116	                            .with_access_key(secret_key)
117	                            .build()?;
118	                        Arc::new(instance)
119	                    }
120	                };
121	
122	                Ok(Self {
123	                    inner: store,
