132	    fn normalize_path(&self, path: &str) -> String {
133	        let path = path.trim_start_matches('/');
134	        if self.prefix.is_empty() {
135	            path.to_string()
136	        } else {
137	            format!("{}/{}", self.prefix.trim_end_matches('/'), path)
138	        }
139	    }
