 56	pub async fn list_active_calls(
 57	    State(state): State<Arc<ConsoleState>>,
 58	    AuthRequired(_): AuthRequired,
 59	    Query(query): Query<ActiveCallListQuery>,
 60	) -> Response {
 61	    let Some(server) = state.sip_server() else {
 62	        return service_unavailable();
 63	    };
 64	
 65	    let limit = query
 66	        .limit
 67	        .unwrap_or(DEFAULT_ACTIVE_CALL_LIMIT)
 68	        .clamp(1, MAX_ACTIVE_CALL_LIMIT);
 69	    let registry = server.active_call_registry.clone();
 70	    let entries = registry.list_recent(limit);
 71	    let payload: Vec<_> = entries
 72	        .into_iter()
 73	        .map(|entry| {
 74	            let session_id = entry.session_id.clone();
 75	            json!({
 76	                "meta": entry,
 77	                "state": snapshot_for(&registry, &session_id),
 78	            })
 79	        })
 80	        .collect();
 81	
 82	    Json(json!({ "data": payload })).into_response()
 83	}
