 94	
 95	    let Some(handle) = registry.get_handle(&session_id) else {
 96	        return (
 97	            StatusCode::NOT_FOUND,
 98	            Json(json!({ "message": "Call not found" })),
 99	        )
100	            .into_response();
101	    };
102	
103	    Json(json!({ "data": json!({
104	        "meta": registry.get(&session_id),
105	        "state": handle.snapshot(),
106	    }) }))
107	    .into_response()
108	}
