110	pub async fn dispatch_call_command(
111	    State(state): State<Arc<ConsoleState>>,
112	    AuthRequired(_): AuthRequired,
113	    AxumPath(session_id): AxumPath<String>,
114	    Json(payload): Json<CallCommandPayload>,
115	) -> Response {
116	    let Some(server) = state.sip_server() else {
117	        return service_unavailable();
118	    };
119	    let registry = server.active_call_registry.clone();
120	
121	    // Verify session exists
122	    let Some(_handle) = registry.get_handle(&session_id) else {
123	        return (
124	            StatusCode::NOT_FOUND,
125	            Json(json!({ "message": "Call not found" })),
126	        )
127	            .into_response();
128	    };
129	
130	    // Use unified dispatch path
131	    use crate::call::runtime::dispatch_console_command;
132	
133	    match dispatch_console_command(&registry, &session_id, payload) {
134	        Ok(result) => {
135	            if result.success {
136	                Json(json!({ "message": "Command dispatched" })).into_response()
137	            } else {
138	                (
139	                    StatusCode::BAD_REQUEST,
140	                    Json(json!({ "message": result.message })),
141	                )
142	                    .into_response()
143	            }
144	        }
145	        Err(e) => (
146	            StatusCode::CONFLICT,
147	            Json(json!({ "message": format!("Failed to deliver command: {}", e) })),
148	        )
149	            .into_response(),
150	    }
151	}
